INSERT INTO submissions (opaque_id, participation_id, task_id, timestamp, language, comment, official)
SELECT 1111111111111111111, p.id, t.id, '2026-10-08 10:00:00+00', 'C++17 / g++', '', true
FROM participations p JOIN users u ON u.id = p.user_id JOIN tasks t ON t.contest_id = p.contest_id
WHERE u.username = 'alice' AND t.name = 'half';
INSERT INTO submission_results (submission_id, dataset_id, compilation_outcome, compilation_text, compilation_tries,
  compilation_stdout, compilation_stderr, compilation_time, compilation_wall_clock_time, compilation_memory,
  evaluation_outcome, evaluation_tries)
SELECT s.id, t.active_dataset_id, 'ok', '{"Compilation succeeded"}', 1, '', '', 0.5, 0.6, 1048576, 'ok', 1
FROM submissions s JOIN tasks t ON t.id = s.task_id WHERE s.opaque_id = 1111111111111111111;
UPDATE submission_results sr SET score=50.0, score_details='[{"idx": "000", "outcome": "Correct", "text": ["Output is correct"], "time": 0.01, "memory": 1048576}, {"idx": "001", "outcome": "Partially correct", "text": ["Output is partially correct"], "time": 0.02, "memory": 2097152}, {"idx": "002", "outcome": "Not correct", "text": ["Output isn''t correct"], "time": 0.03, "memory": null}]', public_score=0.0, public_score_details='[{"idx": "000"}, {"idx": "001"}, {"idx": "002"}]', ranking_score_details=ARRAY[]::text[] FROM submissions s JOIN tasks t ON t.id = s.task_id WHERE sr.submission_id = s.id AND sr.dataset_id = t.active_dataset_id AND t.name = 'half' AND s.opaque_id = 1111111111111111111;
